async function uiUpdate() {
  jobLog("檢查 package server stable …");
  const r = await updateLogic();
  if (r.updated) {
    jobLog(`已安裝 ${r.version}（重啟後生效）`);
    return { ok: true, message: `已更新到 ${r.version} — 按「重啟」生效` };
