async function runJob(kind, fn) {
  if (job.active) return false;
  job.active = true;
  job.kind = kind;
  job.lines = [];
  job.error = null;
  job.message = null;
  job.startedAt = Date.now();
  job.finishedAt = null;
  (async () => {
    try {
      const r = await fn();
      job.message = r.message;
      jobLog(r.ok === false ? `⚠ ${r.message}` : `✓ ${r.message}`);
    } catch (e) {
      job.error = String((e && e.message) || e);
      jobLog(`✗ ${job.error}`);
    } finally {
      job.active = false;
      job.finishedAt = Date.now();
    }
  })();
  return true;
}

