}
`;

  const fakeProcess = `
// fake process.mjs — startAndVerify 不打真 PAAW；hangAround 以固定 exit code 收斂
const S = JSON.parse(process.env.FAKE_SCENARIO || "{}");
const calls = [];
export const __calls = calls;

