    });

    it("updateLogic 回 updated:false（已是最新）→ 仍 exit 0（非錯誤路徑）", async () => {
      const { home, cwd } = caseDirs("update-noop");
      const r = await runGatewayWithFakes(["update"], {
        home,
        cwd,
        scenario: { updated: false, releaseVersion: "1.0.0" },
